    /// Decodes one block length (`ReadBlockLength`): a symbol via
    /// `table` selects a `(offset, nbits)` pair from the fixed 26-entry
    /// `BLOCK_LENGTH_PREFIX_CODE` table, and the real length is
    /// `offset + read(nbits)`.
    fn read_block_length(br: &mut BitReader, table: &HuffmanTable) -> Result<u32> {
        let code = table.decode(br)? as usize;
        let (offset, nbits) = BLOCK_LENGTH_PREFIX_CODE[code];
        Ok(u32::from(offset) + br.read(u32::from(nbits))?)
    }

    /// Decodes a block-type switch for one category (`DecodeBlockType
    /// AndLength`): a symbol from `type_tree` selects the new type -
    /// `0` means "repeat the type used *before* the current one" (a
    /// common alternating-between-two-types pattern), `1` means "the
    /// next sequential type after the current one", anything else is a
    /// literal type index (offset by 2) - then a fresh length is read
    /// via `len_tree`.
    fn decode_block_type_and_length(cat: &mut BlockCategory, br: &mut BitReader) -> Result<()> {
        let type_tree = cat
            .type_tree
            .as_ref()
            .context("Brotli block category has no type tree")?;
        let mut block_type = u32::from(type_tree.decode(br)?);
        let len_tree = cat
            .len_tree
            .as_ref()
            .context("Brotli block category has no length tree")?;
        cat.length = read_block_length(br, len_tree)?;
        if block_type == 1 {
            block_type = cat.type_rb[1] + 1;
        } else if block_type == 0 {
            block_type = cat.type_rb[0];
        } else {
            block_type -= 2;
        }
        if block_type >= cat.num_types {
            block_type -= cat.num_types;
        }
        cat.type_rb = [cat.type_rb[1], block_type];
        Ok(())
    }

    /// Decodes one context map (`DecodeContextMap`): `NTREES =
    /// read_var_len_uint8() + 1`; if `NTREES <= 1` every context maps to
    /// tree 0. Otherwise a Huffman code over `NTREES + max_run_length`
    /// symbols is read (an optional leading bit selects RLE-of-zeroes
    /// support and its own maximum run-length prefix), then
    /// `context_map_size` entries are decoded - a decoded value of `0`
    /// writes a single zero, a value above `max_run_length` writes one
    /// literal tree index (shifted down by `max_run_length`), and
    /// anything else is an RLE-zero-run whose length is `read(code) +
    /// (1 << code)`. Finally an optional inverse move-to-front pass
    /// (RFC 7932's own well-known MTF algorithm) may be applied to the
    /// whole map.
    fn decode_context_map(br: &mut BitReader, context_map_size: u32) -> Result<(Vec<u8>, u32)> {
        let num_htrees = read_var_len_uint8(br)? + 1;
        let mut map = vec![0u8; context_map_size as usize];
        if num_htrees <= 1 {
            return Ok((map, num_htrees));
        }
        let peek5 = br.peek(5);
        let max_run_length_prefix = if peek5 & 1 != 0 {
            br.consume(5);
            (peek5 >> 1) + 1
        } else {
            br.consume(1);
            0
        };
        let alphabet_size = num_htrees + max_run_length_prefix;
        let code_table = read_huffman_code(br, alphabet_size, alphabet_size)?;
        let mut index = 0usize;
        while index < map.len() {
            let code = u32::from(code_table.decode(br)?);
            if code == 0 {
                map[index] = 0;
                index += 1;
                continue;
            }
            if code > max_run_length_prefix {
                map[index] = (code - max_run_length_prefix) as u8;
                index += 1;
                continue;
            }
            let extra = br.read(code)?;
            let reps = (extra + (1 << code)) as usize;
            if index + reps > map.len() {
                bail!("Brotli context map run-length exceeds the map's own size");
            }
            for _ in 0..reps {
                map[index] = 0;
                index += 1;
            }
        }
        if br.read(1)? != 0 {
            inverse_move_to_front(&mut map);
        }
        Ok((map, num_htrees))
    }

    /// The standard inverse move-to-front transform (`InverseMoveToFront
    /// Transform`), applied in place: each value `v` in the sequence is
    /// replaced by "the symbol currently at position `v` of a 256-entry
    /// move-to-front list", and that symbol is then moved to the front
    /// of the list.
    fn inverse_move_to_front(values: &mut [u8]) {
        let mut mtf = [0u8; 256];
        for (i, slot) in mtf.iter_mut().enumerate() {
            *slot = i as u8;
        }
        for v in values.iter_mut() {
            let index = *v as usize;
            let value = mtf[index];
            *v = value;
            for i in (1..=index).rev() {
                mtf[i] = mtf[i - 1];
            }
            mtf[0] = value;
        }
    }

