    /// Cross-verification oracle for the hand-rolled SQLite reader
    /// (`sqlite_support` - see Cargo.toml) - a near-verbatim copy of this
    /// project's own former `rusqlite`-based `columns_from_sqlite`, kept
    /// as a dev-only dependency for exactly this purpose. Unlike every
    /// other oracle in this file, `rusqlite` was never itself a Rust
    /// reimplementation of the on-disk format - it's an FFI binding over
    /// the real, linked SQLite C library - so this comparison is against
    /// a genuinely independent codebase, not just a different Rust parser
    /// of the same spec.
    #[cfg(all(test, feature = "sqlite"))]
    fn columns_from_sqlite_via_rusqlite(
        path: &Path,
        nrows: Option<usize>,
        n_samples: usize,
    ) -> Result<Vec<(String, Vec<ColumnProfile>)>> {
        use rusqlite::Connection;
        use rusqlite::types::ValueRef;

        let conn = Connection::open(path).with_context(|| format!("failed to open {path:?}"))?;
        let mut table_stmt = conn
            .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
            .with_context(|| format!("failed to list tables in {path:?}"))?;
        let table_names: Vec<String> = table_stmt
            .query_map([], |row| row.get::<_, String>(0))
            .and_then(Iterator::collect)
            .with_context(|| format!("failed to list tables in {path:?}"))?;
        drop(table_stmt);

        if table_names.is_empty() {
            bail!("no user tables found in {path:?}");
        }

        let mut out = Vec::new();
        for table in table_names {
            let query = match nrows {
                Some(n) => format!("SELECT * FROM \"{table}\" LIMIT {n}"),
                None => format!("SELECT * FROM \"{table}\""),
            };
            let mut stmt = conn
                .prepare(&query)
                .with_context(|| format!("failed to query table '{table}' in {path:?}"))?;
            let col_names: Vec<String> =
                stmt.column_names().iter().map(|s| s.to_string()).collect();
            let n_cols = col_names.len();

            let mut raw: Vec<Vec<Option<String>>> = vec![Vec::new(); n_cols];
            let mut kind_counts: Vec<SqlKindCounts> = vec![SqlKindCounts::default(); n_cols];

            let mut rows = stmt
                .query([])
                .with_context(|| format!("failed to query table '{table}' in {path:?}"))?;
            while let Some(row) = rows
                .next()
                .with_context(|| format!("failed reading a row from '{table}' in {path:?}"))?
            {
                for i in 0..n_cols {
                    let value_ref = row.get_ref(i).with_context(|| {
                        format!("failed reading a value from '{table}' in {path:?}")
                    })?;
                    let value = match value_ref {
                        ValueRef::Null => None,
                        ValueRef::Integer(v) => {
                            kind_counts[i].increment(SqlKind::Integer);
                            Some(v.to_string())
                        }
                        ValueRef::Real(v) => {
                            kind_counts[i].increment(SqlKind::Real);
                            Some(v.to_string())
                        }
                        ValueRef::Text(t) => {
                            kind_counts[i].increment(SqlKind::Text);
                            Some(String::from_utf8_lossy(t).into_owned())
                        }
                        ValueRef::Blob(b) => {
                            kind_counts[i].increment(SqlKind::Blob);
                            Some(format!("<blob: {} bytes>", b.len()))
                        }
                    };
                    raw[i].push(value);
                }
            }

            let mut profiles = Vec::new();
            for (i, name) in col_names.into_iter().enumerate() {
                let non_null: Vec<String> = raw[i].iter().filter_map(|v| v.clone()).collect();
                let current_type = if kind_counts[i].is_empty() {
                    "null".to_string()
                } else {
                    describe_sql_kinds(&kind_counts[i])
                };
                let col = ColumnInput {
                    name,
                    current_type,
                    raw_values: non_null,
                    total: raw[i].len(),
                    skip_heuristics: false,
                };
                profiles.push(profile_column(col, n_samples));
            }
            out.push((table, profiles));
        }
        Ok(out)
    }

    #[cfg(feature = "sqlite")]
    #[test]
    fn sqlite_reader_matches_the_rusqlite_crate_output_exactly() {
        for f in [
            "tests/fixtures/sample.sqlite",
            "tests/fixtures/edge_sqlite_view_excluded.sqlite",
            "tests/fixtures/type_detection.sqlite",
            "tests/fixtures/edge_zero_rows.sqlite",
            "tests/fixtures/edge_sqlite_overflow_pages.sqlite",
            "tests/fixtures/edge_sqlite_table_level_primary_key.sqlite",
        ] {
            let path = Path::new(f);
            let mine = sqlite_support::columns_from_sqlite(path, None, 100)
                .unwrap_or_else(|e| panic!("{f}: hand-rolled reader failed: {e:?}"));
            let theirs = columns_from_sqlite_via_rusqlite(path, None, 100)
                .unwrap_or_else(|e| panic!("{f}: rusqlite-based oracle failed: {e:?}"));

            assert_eq!(
                mine.iter().map(|(t, _)| t).collect::<Vec<_>>(),
                theirs.iter().map(|(t, _)| t).collect::<Vec<_>>(),
                "{f}: table names differ"
            );
            for ((mt, mcols), (_, tcols)) in mine.iter().zip(theirs.iter()) {
                assert_eq!(
                    mcols.iter().map(|c| &c.name).collect::<Vec<_>>(),
                    tcols.iter().map(|c| &c.name).collect::<Vec<_>>(),
                    "{f} table '{mt}': column names differ"
                );
                for (m, t) in mcols.iter().zip(tcols.iter()) {
                    assert_eq!(
                        m.current_type, t.current_type,
                        "{f} table '{mt}' col '{}': current_type",
                        m.name
                    );
                    assert_eq!(
                        m.ideal_type, t.ideal_type,
                        "{f} table '{mt}' col '{}': ideal_type",
                        m.name
                    );
                    assert_eq!(
                        m.sample_values, t.sample_values,
                        "{f} table '{mt}' col '{}': sample_values",
                        m.name
                    );
                }
            }
        }
    }

    /// Cross-verification oracle for the hand-rolled SAS7BDAT reader
    /// (`sas7bdat_support` - see Cargo.toml), a near-verbatim copy of
    /// this project's own former `sas7bdat`-crate-based reader.
    #[cfg(all(test, feature = "sas7bdat"))]
    fn sas_logical_type_label_via_sas7bdat_crate(t: sas7bdat::LogicalType) -> &'static str {
        use sas7bdat::LogicalType;
        match t {
            LogicalType::Integer => "i64",
            LogicalType::Float => "f64",
            LogicalType::String | LogicalType::Bytes => "String",
            LogicalType::Date => "Date",
            LogicalType::DateTime => "Timestamp",
            LogicalType::Time => "Time",
        }
    }

    #[cfg(all(test, feature = "sas7bdat"))]
    fn sas_cell_to_string_via_sas7bdat_crate(v: &sas7bdat::CellValue) -> Option<String> {
        use sas7bdat::CellValue;
        match v {
            CellValue::Null => None,
            CellValue::Int32(x) => Some(x.to_string()),
            CellValue::Int64(x) => Some(x.to_string()),
            CellValue::Float64(x) => Some(x.to_string()),
            CellValue::Str(s) => {
                let s = s.trim();
                if s.is_empty() {
                    None
                } else {
                    Some(s.to_string())
                }
            }
            CellValue::Bytes(b) => Some(b.iter().map(|byte| format!("{byte:02x}")).collect()),
            CellValue::Date(d) => {
                EpochDate::from_days(i64::from(d.unix_days())).map(|date| date.format_ymd())
            }
            CellValue::DateTime(dt) => {
                EpochDateTime::from_unix_seconds(dt.unix_seconds(), 0).map(|dt| dt.format_space())
            }
            CellValue::Time(t) => EpochTime::from_seconds_since_midnight(
                u32::try_from(t.seconds_since_midnight).unwrap_or(0),
                0,
            )
            .map(|nt| nt.format_hms()),
        }
    }

    #[cfg(all(test, feature = "sas7bdat"))]
    fn columns_from_sas7bdat_via_sas7bdat_crate(
        path: &Path,
        nrows: Option<usize>,
        n_samples: usize,
    ) -> Result<Vec<ColumnProfile>> {
        use std::ops::ControlFlow;

        let ds = sas7bdat::Dataset::open(path)
            .map_err(|e| anyhow!("{e}"))
            .with_context(|| format!("failed to open {path:?}"))?;

        let names: Vec<String> = ds.columns().iter().map(|c| c.name.clone()).collect();
        let current_types: Vec<&'static str> = ds
            .columns()
            .iter()
            .map(|c| sas_logical_type_label_via_sas7bdat_crate(c.logical_type))
            .collect();

        let mut raw: Vec<Vec<Option<String>>> = vec![Vec::new(); names.len()];
        let mut total = 0usize;
        ds.scan()
            .visit_rows(|row| {
                for (col_idx, value) in row.iter().enumerate() {
                    raw[col_idx].push(sas_cell_to_string_via_sas7bdat_crate(value));
                }
                total += 1;
                if nrows.is_some_and(|limit| total >= limit) {
                    Ok(ControlFlow::Break(()))
                } else {
                    Ok(ControlFlow::Continue(()))
                }
            })
            .map_err(|e| anyhow!("{e}"))
            .with_context(|| format!("failed reading records from {path:?}"))?;

        let mut columns = Vec::new();
        for ((name, current_type), values) in names.into_iter().zip(current_types).zip(raw) {
            let non_null: Vec<String> = values.into_iter().flatten().collect();
            columns.push(profile_column(
                ColumnInput {
                    name,
                    current_type: current_type.to_string(),
                    raw_values: non_null,
                    total,
                    skip_heuristics: false,
                },
                n_samples,
            ));
        }
        Ok(columns)
    }

    #[cfg(feature = "sas7bdat")]
    #[test]
    fn sas7bdat_reader_matches_the_sas7bdat_crate_output_exactly() {
        for f in ["tests/fixtures/sas7bdat_people_nonascii.sas7bdat"] {
            let path = Path::new(f);
            let mine = sas7bdat_support::columns_from_sas7bdat(path, None, 100)
                .unwrap_or_else(|e| panic!("{f}: hand-rolled reader failed: {e:?}"));
            let theirs = columns_from_sas7bdat_via_sas7bdat_crate(path, None, 100)
                .unwrap_or_else(|e| panic!("{f}: sas7bdat-crate-based oracle failed: {e:?}"));

            assert_eq!(
                mine.iter().map(|c| &c.name).collect::<Vec<_>>(),
                theirs.iter().map(|c| &c.name).collect::<Vec<_>>(),
                "{f}: column names differ"
            );
            for (m, t) in mine.iter().zip(theirs.iter()) {
                assert_eq!(
                    m.current_type, t.current_type,
                    "{f} col '{}': current_type",
                    m.name
                );
                assert_eq!(
                    m.sample_values, t.sample_values,
                    "{f} col '{}': sample_values",
                    m.name
                );
                assert_eq!(
                    m.missing_pct, t.missing_pct,
                    "{f} col '{}': missing_pct",
                    m.name
                );
            }
        }
    }

    /// Both readers must agree on success/failure for genuinely bad
    /// input - real-fixture comparisons are the assertion above; this
    /// one covers `malformed_garbage.sas7bdat` separately since a clean
    /// rejection has no field-by-field output to compare.
    #[cfg(feature = "sas7bdat")]
    #[test]
    fn sas7bdat_reader_agrees_with_the_sas7bdat_crate_on_malformed_input() {
        let path = Path::new("tests/fixtures/malformed_garbage.sas7bdat");
        let mine = sas7bdat_support::columns_from_sas7bdat(path, None, 100);
        let theirs = columns_from_sas7bdat_via_sas7bdat_crate(path, None, 100);
        assert_eq!(mine.is_ok(), theirs.is_ok());
    }

    /// Test-only: `ambers` is a dev-dependency that was never a runtime
    /// dependency of this project's own `spss` feature to begin with (see
    /// Cargo.toml) - `spss_support`'s own hand-rolled reader was built and
    /// verified directly against `ambers`'s own source from the start.
    /// This function's only job is producing the "expected" side of
    /// `spss_reader_matches_the_ambers_crate_output_exactly` by reading the
    /// same file through `ambers`'s real, independent Arrow-based decoder
    /// and reducing its `RecordBatch` to the same `ColumnProfile` shape
    /// this project's own reader produces, via the same shared
    /// `array_value_to_string`/`profile_column` machinery this project's
    /// Parquet/Arrow IPC oracles already lean on for exactly this reason.
    #[cfg(all(test, feature = "spss"))]
    fn columns_from_spss_via_ambers_crate(
        path: &Path,
        n_samples: usize,
    ) -> Result<Vec<ColumnProfile>> {
        use ambers::MissingSpec;
        use arrow57::array::Float64Array;
        use arrow57::datatypes::DataType;

        let (batch, meta) = ambers::read_sav(path)
            .map_err(|e| Error::from(std::io::Error::other(e.to_string())))?;
        let schema = batch.schema();

        let mut columns = Vec::with_capacity(schema.fields().len());
        for (i, field) in schema.fields().iter().enumerate() {
            let array = batch.column(i);
            let is_numeric = matches!(
                field.data_type(),
                DataType::Float64
                    | DataType::Date32
                    | DataType::Timestamp(..)
                    | DataType::Duration(..)
            );
            let current_type = if is_numeric { "f64" } else { "String" };
            // `ambers`'s own `RecordBatch` only ever nulls out SYSMIS - a
            // *user-declared* missing value (e.g. "999 means Refused",
            // this project's own `edge_spss_missing_values.sav` fixture)
            // stays a genuine, present value in the batch, with the
            // declaration surfaced separately in `meta.
            // variable_missing_values` instead (a real, independent-
            // library design choice, not a defect - "missing" here is a
            // domain decision a caller opts into, not a data-integrity
            // one). This project's own reader excludes both, so the
            // oracle applies the same declared-missing filtering here to
            // keep the comparison apples-to-apples rather than either
            // loosening this project's own reader or weakening the
            // assertion.
            let specs: Vec<MissingSpec> = meta
                .variable_missing_values
                .get(field.name())
                .cloned()
                .unwrap_or_default();
            let total = array.len();
            let mut raw_values = Vec::with_capacity(total);
            // Arrow's own `Display` for a plain `Float64` always keeps a
            // decimal point (`"1.0"`), unlike this project's own
            // established convention (a whole-number-valued f64 renders
            // without a trailing ".0", the same as dBase/Stata/SAS7BDAT's
            // readers already do) - normalized here, in the oracle's own
            // wrapper, rather than changing this project's reader to match
            // an oracle-specific formatting quirk it doesn't otherwise
            // need to (the same "don't trust the oracle's own rendering
            // verbatim" treatment this project's Parquet Float16 oracle
            // comparison already needed for an analogous reason).
            let plain_floats = array.as_any().downcast_ref::<Float64Array>();
            for row in 0..total {
                if array.is_null(row) {
                    continue;
                }
                if let Some(floats) = plain_floats {
                    let v = floats.value(row);
                    let excluded = specs.iter().any(|spec| match spec {
                        MissingSpec::Value(mv) => *mv == v,
                        MissingSpec::Range { lo, hi } => v >= *lo && v <= *hi,
                        MissingSpec::StringValue(_) => false,
                    });
                    if excluded {
                        continue;
                    }
                    raw_values.push(if v.fract() == 0.0 && v.abs() < 1e15 {
                        format!("{v:.0}")
                    } else {
                        v.to_string()
                    });
                } else {
                    let s = arrow57::util::display::array_value_to_string(array, row)
                        .context("ambers oracle: failed to stringify a cell")?;
                    let excluded = specs.iter().any(|spec| {
                        matches!(spec, MissingSpec::StringValue(sv) if sv.trim_end() == s.trim_end())
                    });
                    if excluded {
                        continue;
                    }
                    raw_values.push(s);
                }
            }
            columns.push(profile_column(
                ColumnInput {
                    name: field.name().clone(),
                    current_type: current_type.to_string(),
                    raw_values,
                    total,
                    skip_heuristics: false,
                },
                n_samples,
            ));
        }
        Ok(columns)
    }

    /// Cross-verification oracle for the hand-rolled SPSS reader
    /// (`spss_support` - see Cargo.toml) against the real `ambers` crate,
    /// kept as a dev-only dependency for exactly this purpose. Compares
    /// column names, the numeric/string current-type split, and
    /// `sample_values` (not full `raw_values`) - `ambers` resolves a
    /// native SPSS date to Arrow's own `Date32` and a datetime to a
    /// microsecond `Timestamp`, and while both readers agree on the
    /// resulting calendar date/time (confirmed directly - Arrow's own
    /// `Display` for both types already renders the same ISO shape this
    /// project's own `EpochDate`/`EpochDateTime` formatters produce), a
    /// looser `sample_values`-only comparison keeps this test from being
    /// needlessly brittle against a future rendering-convention change in
    /// either crate for a value this project never claims byte-identical
    /// formatting on in the first place (e.g. `ideal_type`'s own
    /// downstream type inference, not raw string equality, is what this
    /// project actually guarantees for a date column - see the design
    /// philosophy section in CLAUDE.md).
    #[cfg(feature = "spss")]
    #[test]
    fn spss_reader_matches_the_ambers_crate_output_exactly() {
        for f in [
            "tests/fixtures/type_detection.sav",
            "tests/fixtures/edge_spss_missing_values.sav",
            "tests/fixtures/edge_spss_very_long_string.sav",
            "tests/fixtures/edge_spss_bytecode_compressed.sav",
            "tests/fixtures/edge_spss_uncompressed_equivalent.sav",
        ] {
            let path = Path::new(f);
            let mine = spss_support::columns_from_spss(path, None, 100)
                .unwrap_or_else(|e| panic!("{f}: hand-rolled reader failed: {e:?}"));
            let theirs = columns_from_spss_via_ambers_crate(path, 100)
                .unwrap_or_else(|e| panic!("{f}: ambers-crate-based oracle failed: {e:?}"));

            assert_eq!(
                mine.iter().map(|c| &c.name).collect::<Vec<_>>(),
                theirs.iter().map(|c| &c.name).collect::<Vec<_>>(),
                "{f}: column names differ"
            );
            for (m, t) in mine.iter().zip(theirs.iter()) {
                assert_eq!(
                    m.current_type, t.current_type,
                    "{f} col '{}': current_type",
                    m.name
                );
                assert_eq!(
                    m.missing_pct, t.missing_pct,
                    "{f} col '{}': missing_pct",
                    m.name
                );
                assert_eq!(
                    m.sample_values, t.sample_values,
                    "{f} col '{}': sample_values",
                    m.name
                );
            }
        }
    }

    /// Both readers must agree on success/failure for genuinely bad
    /// input - real-fixture comparisons are the assertion above; this one
    /// covers `malformed_garbage.sav` separately since a clean rejection
    /// has no field-by-field output to compare.
    #[cfg(feature = "spss")]
    #[test]
    fn spss_reader_agrees_with_the_ambers_crate_on_malformed_input() {
        let path = Path::new("tests/fixtures/malformed_garbage.sav");
        let mine = spss_support::columns_from_spss(path, None, 100);
        let theirs = columns_from_spss_via_ambers_crate(path, 100);
        assert_eq!(mine.is_ok(), theirs.is_ok());
    }

    /// Test-only: `orc-rust` is a dev-dependency that was never a runtime
    /// dependency of this project's own `orc` feature to begin with (see
    /// Cargo.toml) - `orc_support`'s own hand-rolled reader was built and
    /// verified directly against `orc-rust`'s own source (plus the
    /// official `apache/orc-format` specification) from the start, the
    /// same "went straight to a hand-roll, never shipped the real crate
    /// first" story SPSS/`ambers` already tell. This function's only job
    /// is producing the "expected" side of
    /// `orc_reader_matches_the_orc_rust_crate_output_exactly` by reading
    /// the same file through `orc-rust`'s real, independent Arrow-based
    /// decoder.
    #[cfg(all(test, feature = "orc"))]
    fn columns_from_orc_via_orc_rust_crate(
        path: &Path,
        n_samples: usize,
    ) -> Result<Vec<ColumnProfile>> {
        use arrow58::array::Float32Array;
        use arrow58::array::Float64Array;
        use arrow58::datatypes::DataType;

        let file = std::fs::File::open(path).context("failed to open ORC fixture")?;
        let builder = orc_rust::ArrowReaderBuilder::try_new(file)
            .map_err(|e| Error::from(std::io::Error::other(e.to_string())))?;
        let schema = builder.schema();
        let reader = builder.build();

        let n = schema.fields().len();
        let mut current_types: Vec<&'static str> = Vec::with_capacity(n);
        for field in schema.fields() {
            let t = match field.data_type() {
                DataType::Boolean => "bool",
                DataType::Int8 | DataType::Int16 | DataType::Int32 | DataType::Int64 => "i64",
                DataType::Float32 | DataType::Float64 => "f64",
                DataType::Utf8 | DataType::Binary => "String",
                DataType::Decimal128(..) => "Decimal",
                DataType::Date32 => "Date",
                DataType::Timestamp(..) => "Timestamp",
                other => bail!("orc-rust oracle: unhandled Arrow data type {other:?}"),
            };
            current_types.push(t);
        }
        let mut raw_values: Vec<Vec<String>> = vec![Vec::new(); n];
        let mut total = 0usize;

        for batch in reader {
            let batch = batch.map_err(|e| Error::from(std::io::Error::other(e.to_string())))?;
            total += batch.num_rows();
            #[allow(clippy::needless_range_loop)]
            for i in 0..n {
                let array = batch.column(i);
                let plain_f64 = array.as_any().downcast_ref::<Float64Array>();
                let plain_f32 = array.as_any().downcast_ref::<Float32Array>();
                for row in 0..array.len() {
                    if array.is_null(row) {
                        continue;
                    }
                    // Arrow's own `Display` for a plain float always
                    // keeps a trailing decimal point (`"1.0"`), unlike
                    // this project's own established convention - the
                    // same oracle-specific quirk the SPSS/`ambers` oracle
                    // above already had to normalize away, for the
                    // identical reason.
                    let s = if let Some(floats) = plain_f64 {
                        let v = floats.value(row);
                        if v.fract() == 0.0 && v.abs() < 1e15 {
                            format!("{v:.0}")
                        } else {
                            v.to_string()
                        }
                    } else if let Some(floats) = plain_f32 {
                        let v = floats.value(row);
                        if v.fract() == 0.0 && v.abs() < 1e7 {
                            format!("{v:.0}")
                        } else {
                            v.to_string()
                        }
                    } else if matches!(array.data_type(), DataType::Binary) {
                        let bin = array
                            .as_any()
                            .downcast_ref::<arrow58::array::BinaryArray>()
                            .context("orc-rust oracle: expected a BinaryArray")?;
                        bin.value(row).iter().map(|b| format!("{b:02x}")).collect()
                    } else if let Some(ts) = array
                        .as_any()
                        .downcast_ref::<arrow58::array::TimestampNanosecondArray>()
                    {
                        // Arrow's own `Display` for a timestamp trims
                        // trailing-zero fractional digits (and omits the
                        // fraction entirely for an exact whole second),
                        // unlike this project's own fixed 9-digit
                        // nanosecond rendering - both represent the
                        // identical instant, so this re-derives the
                        // string through this project's own formatter
                        // for an apples-to-apples comparison, the same
                        // "don't trust the oracle's own rendering
                        // verbatim" treatment every other oracle in this
                        // file already needs somewhere.
                        let nanos_since_epoch = ts.value(row);
                        EpochDateTime::from_unix_seconds(
                            nanos_since_epoch.div_euclid(1_000_000_000),
                            nanos_since_epoch.rem_euclid(1_000_000_000) as u32,
                        )
                        .map(|dt| dt.format_t_frac(9))
                        .context("orc-rust oracle: timestamp out of representable range")?
                    } else {
                        arrow58::util::display::array_value_to_string(array, row)
                            .context("orc-rust oracle: failed to stringify a cell")?
                    };
                    raw_values[i].push(s);
                }
            }
        }

        let mut columns = Vec::with_capacity(n);
        for (i, field) in schema.fields().iter().enumerate() {
            columns.push(profile_column(
                ColumnInput {
                    name: field.name().clone(),
                    current_type: current_types[i].to_string(),
                    raw_values: std::mem::take(&mut raw_values[i]),
                    total,
                    skip_heuristics: false,
                },
                n_samples,
            ));
        }
        Ok(columns)
    }

    /// Cross-verification oracle for the hand-rolled ORC reader
    /// (`orc_support` - see Cargo.toml) against the real `orc-rust`
    /// crate, kept as a dev-only dependency for exactly this purpose.
    #[cfg(feature = "orc")]
    #[test]
    fn orc_reader_matches_the_orc_rust_crate_output_exactly() {
        for f in [
            "tests/fixtures/type_detection.orc",
            "tests/fixtures/edge_orc_rle_v2_encodings.orc",
            "tests/fixtures/edge_orc_missing_values.orc",
            "tests/fixtures/edge_orc_dictionary_strings.orc",
            "tests/fixtures/edge_orc_binary_and_bool.orc",
            "tests/fixtures/edge_orc_compression_none.orc",
            "tests/fixtures/edge_orc_compression_zlib.orc",
            "tests/fixtures/edge_orc_compression_snappy.orc",
            "tests/fixtures/edge_orc_compression_zstd.orc",
            "tests/fixtures/edge_orc_compression_lz4.orc",
            "tests/fixtures/edge_orc_decimal_and_timestamp.orc",
        ] {
            let path = Path::new(f);
            let mine = orc_support::columns_from_orc(path, None, 100)
                .unwrap_or_else(|e| panic!("{f}: hand-rolled reader failed: {e:?}"));
            let theirs = columns_from_orc_via_orc_rust_crate(path, 100)
                .unwrap_or_else(|e| panic!("{f}: orc-rust-crate-based oracle failed: {e:?}"));

            assert_eq!(
                mine.iter().map(|c| &c.name).collect::<Vec<_>>(),
                theirs.iter().map(|c| &c.name).collect::<Vec<_>>(),
                "{f}: column names differ"
            );
            for (m, t) in mine.iter().zip(theirs.iter()) {
                assert_eq!(
                    m.current_type, t.current_type,
                    "{f} col '{}': current_type",
                    m.name
                );
                assert_eq!(
                    m.missing_pct, t.missing_pct,
                    "{f} col '{}': missing_pct",
                    m.name
                );
                assert_eq!(
                    m.sample_values, t.sample_values,
                    "{f} col '{}': sample_values",
                    m.name
                );
            }
        }
    }

